@MainActor func testOrdinaryButtonsUseCurrentItemAfterReuse() {
        var events: [String] = []
        let view = ReusableMessageActions { events.append($0 + ":" + $1.rawValue) }
        view.configure(id: "a", title: "Alpha", enabled: true)
        view.configure(id: "b", title: "Beta", enabled: true)
        view.archiveButton.sendActions(for: .touchUpInside)
        view.deleteButton.sendActions(for: .touchUpInside)
        XCTAssertEqual(events, ["b:archive", "b:delete"])
        XCTAssertEqual(view.archiveButton.accessibilityLabel, "Archive Beta")
        XCTAssertEqual(view.deleteButton.accessibilityLabel, "Delete Beta")
        XCTAssertFalse(view.isAccessibilityElement)
        XCTAssertFalse(view.accessibilityElementsHidden)
    }

@MainActor func testRetainedOldActionCannotAffectReusedView() throws {
        var events: [String] = []
        let view = ReusableMessageActions { events.append($0 + ":" + $1.rawValue) }
        view.configure(id: "a", title: "Alpha", enabled: true)
        let old = try XCTUnwrap(view.summary.accessibilityCustomActions?.first)
        view.configure(id: "b", title: "Beta", enabled: true)
        XCTAssertEqual(old.actionHandler?(old), false)
        XCTAssertTrue(events.isEmpty)
    }

@MainActor func testDisableAndReenableRefreshesBothActionPaths() throws {
        var count = 0
        let view = ReusableMessageActions { _, _ in count += 1 }
        view.configure(id: "a", title: "Alpha", enabled: false)
        let action = try XCTUnwrap(view.summary.accessibilityCustomActions?.first)
        XCTAssertFalse(view.archiveButton.isEnabled)
        XCTAssertFalse(view.deleteButton.isEnabled)
        XCTAssertEqual(action.actionHandler?(action), false)
        view.archiveButton.sendActions(for: .touchUpInside)
        XCTAssertEqual(count, 0)
        view.configure(id: "a", title: "Alpha", enabled: true)
        XCTAssertTrue(view.archiveButton.isEnabled)
        view.archiveButton.sendActions(for: .touchUpInside)
        XCTAssertEqual(count, 1)
    }

@MainActor func testRetainedCustomActionDoesNotKeepViewAlive() throws {
        var view: ReusableMessageActions? = ReusableMessageActions { _, _ in }
        view?.configure(id: "a", title: "Alpha", enabled: true)
        weak var weakView = view
        let action = try XCTUnwrap(view?.summary.accessibilityCustomActions?.first)
        view = nil
        XCTAssertNil(weakView)
        XCTAssertEqual(action.actionHandler?(action), false)
    }

@MainActor func testNativeActionIdentifierReplacesPreviousHandler() {
        let control = UIControl(), identifier = UIAction.Identifier("update")
        var events: [String] = []
        control.addAction(UIAction(identifier: identifier) { _ in events.append("old") }, for: .valueChanged)
        control.addAction(UIAction(identifier: identifier) { _ in events.append("new") }, for: .valueChanged)
        control.sendActions(for: .valueChanged)
        XCTAssertEqual(events, ["new"])
    }

@MainActor func testReconfigurationClearsStaleHintAndValue() {
        let button = UIButton(type: .system)
        SemanticConfiguration.configure(button, selected: true, hint: "Old hint")
        SemanticConfiguration.configure(button, selected: false, hint: nil)
        XCTAssertNil(button.accessibilityHint)
        XCTAssertEqual(button.accessibilityValue, "Not saved")
    }

func testReplacementRejectsOldItemCompletion() {
        let o = MediaLoadOwner(); var a: Reply!, b: Reply!
        o.replace(item()) { _, reply in a = reply }; o.replace(item()) { _, reply in b = reply }
        b(.success("new")); a(.success("old")); XCTAssertEqual(o.value, "new")
    }

func testSameItemNewRequestRejectsOldGeneration() {
        let o = MediaLoadOwner(), i = item(); var a: Reply!, b: Reply!
        o.replace(i) { _, r in a = r }; o.replace(i) { _, r in b = r }
        a(.success("old")); XCTAssertNil(o.value); XCTAssertEqual(o.state, "loading")
        b(.success("new")); XCTAssertEqual(o.value, "new")
    }

func testExternalReplacementRejectsOldResult() {
        let o = MediaLoadOwner(); var done: Reply!
        let original = item(); o.replace(original) { _, r in done = r }; o.player.replaceCurrentItem(with: item())
        withExtendedLifetime(original) { done(.success("old")) }; XCTAssertNil(o.value); XCTAssertEqual(o.state, "superseded")
    }

func testFontsMatchEffectiveLargeTextEnvironment() {
        let row = cell()
        setSize(row, .accessibilityExtraExtraExtraLarge)
        configure(row)
        for label in [row.nameLabel, row.stateLabel] {
            let expected = UIFont.preferredFont(forTextStyle: .body, compatibleWith: label.traitCollection)
            XCTAssertEqual(label.font.pointSize, expected.pointSize, accuracy: 0.01)
            XCTAssertEqual(label.font.fontDescriptor.object(forKey: .textStyle) as? String, UIFont.TextStyle.body.rawValue)
        }
    }

func testRepeatedSizeTransitionsDoNotAccumulateScaling() {
        let row = cell()
        for size: UIContentSizeCategory in [.large, .accessibilityExtraExtraExtraLarge, .small, .large] {
            setSize(row, size)
            configure(row)
            configure(row)
            for label in [row.nameLabel, row.stateLabel] {
                XCTAssertEqual(label.font.pointSize,
                               UIFont.preferredFont(forTextStyle: .body, compatibleWith: label.traitCollection).pointSize,
                               accuracy: 0.01)
            }
        }
    }

func testFlexibleTextConfigurationAndNoFixedEnclosingHeight() {
        let summary = CheckoutSummary(payButton: UIButton(type: .system))
        summary.update(total: "USD 123,456,789,012.34")
        XCTAssertEqual(summary.totalLabel.text, "USD 123,456,789,012.34")
        XCTAssertEqual(summary.totalLabel.numberOfLines, 0)
        XCTAssertTrue(summary.totalLabel.adjustsFontForContentSizeCategory)
        XCTAssertNotNil(summary.totalLabel.font.fontDescriptor.object(forKey: .textStyle))
        XCTAssertFalse(summary.totalLabel.adjustsFontSizeToFitWidth)
        XCTAssertFalse(summary.constraints.contains {
            $0.isActive && $0.firstAttribute == .height && $0.relation == .equal && $0.secondItem == nil
        })
    }

func testLongLocalizedContentRemainsVerbatim() {
        let row = cell()
        let name = String(repeating: "Livraison du soir avec instructions detaillees. ", count: 12)
        setSize(row, .accessibilityExtraExtraExtraLarge)
        row.configure(name: name, chosen: true, selectedText: "Selectionnee", unselectedText: "Non selectionnee")
        XCTAssertEqual(row.nameLabel.text, name)
        XCTAssertEqual(row.accessibilityLabel, name)
        XCTAssertEqual(row.stateLabel.text, "Selectionnee")
        XCTAssertEqual(row.accessibilityValue, "Selectionnee")
    }

func testSelfSizingConfigurationAndVerticalConstraintChain() {
        let row = cell(), table = UITableView()
        table.rowHeight = 44
        AccessibleChoiceCell.configureSizing(table)
        XCTAssertEqual(table.rowHeight, UITableView.automaticDimension)
        XCTAssertGreaterThan(table.estimatedRowHeight, 0)
        XCTAssertEqual(row.textStack.axis, .vertical)
        let edges = row.contentView.constraints.filter {
            $0.isActive && ($0.firstItem as? UIView) === row.textStack &&
            ($0.secondItem as? UIView) === row.contentView && $0.relation == .equal
        }
        XCTAssertEqual(edges.filter { $0.firstAttribute == .top && $0.secondAttribute == .top }.count, 1)
        XCTAssertEqual(edges.filter { $0.firstAttribute == .bottom && $0.secondAttribute == .bottom }.count, 1)
        for view in [row, row.contentView, row.textStack, row.nameLabel, row.stateLabel] {
            let fixedHeights = view.constraints.filter {
                $0.isActive && $0.firstAttribute == .height && $0.relation == .equal && $0.secondItem == nil
            }
            XCTAssertTrue(fixedHeights.isEmpty)
        }
    }

func testPreservesExistingButtonIdentityTypographyAndTitle() throws {
        let button = UIButton(type: .system)
        button.setTitle("Pay securely", for: .normal)
        let title = try XCTUnwrap(button.titleLabel)
        title.font = .systemFont(ofSize: 19, weight: .semibold)
        title.adjustsFontForContentSizeCategory = false
        let descriptor = try XCTUnwrap(title.font).fontDescriptor
        let summary = CheckoutSummary(payButton: button)
        summary.update(total: "USD 1,234,567.89")
        XCTAssertTrue(summary.payButton === button)
        XCTAssertTrue(title.font.fontDescriptor.isEqual(descriptor))
        XCTAssertFalse(title.adjustsFontForContentSizeCategory)
        XCTAssertEqual(button.title(for: .normal), "Pay securely")
    }

func testRepeatedUpdatesPreserveExistingActionExactlyOnce() {
        let button = UIButton(type: .system)
        var calls = 0
        button.addAction(UIAction { _ in calls += 1 }, for: .primaryActionTriggered)
        let summary = CheckoutSummary(payButton: button)
        for total in ["USD 0.00", "USD 123,456,789.00", "EUR 9,876.54"] {
            summary.update(total: total)
        }
        XCTAssertEqual(calls, 0)
        summary.payButton.sendActions(for: .primaryActionTriggered)
        XCTAssertEqual(calls, 1)
        summary.update(total: "USD 5.00")
        XCTAssertEqual(calls, 1)
        summary.payButton.sendActions(for: .primaryActionTriggered)
        XCTAssertEqual(calls, 2)
        XCTAssertEqual(summary.arrangedSubviews.count, 2)
    }

func testSelectedChildSurvivesSiblingReorder() throws {
        let d = configured(); d.outline.expandItem(try XCTUnwrap(d.nodes["g"])); d.select("b")
        XCTAssertEqual(d.selectedID, "b")
        XCTAssertTrue(d.apply([Item(id: "g", title: "Group", children: [Item(id: "b", title: "Beta"), Item(id: "a", title: "Alpha")])]))
        XCTAssertEqual(d.selectedID, "b")
    }

func testRemovedSelectionClears() {
        let d = configured(); d.select("z")
        XCTAssertTrue(d.apply([Item(id: "only", title: "Only")]))
        XCTAssertNil(d.selectedID)
    }

func testReconfigureClearsStaleSelectionText() {
        let r = RegionState(); r.configure(name: "First", selected: true, reduceTransparency: false)
        r.configure(name: "Second", selected: false, reduceTransparency: false)
        XCTAssertEqual(r.button.accessibilityLabel, "Second")
        XCTAssertEqual(r.status.text, "Not selected")
    }

