func testNilItemDoesNotInvokeLoader() {
        let o = MediaLoadOwner(); var calls = 0
        o.replace(nil) { _, _ in calls += 1 }; XCTAssertEqual(calls, 0); XCTAssertEqual(o.state, "unavailable")
